(()=>{
'use strict';
const sequence=['1s','2s','2p','3s','3p','4s','3d','4p','5s','4d','5p','6s','4f','5d'];
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
class SubshellOrder{
 constructor(){this.mode='order';this.solved=0;this.next()}
 next(){this.done=false;this.revealed=false;this.feedback='';this.size=Math.min(8,3+Math.floor(this.solved/2));const start=Math.floor(Math.random()*(sequence.length-this.size+1));this.target=sequence.slice(start,start+this.size);this.cards=shuffle(this.target);if(this.cards.every((c,i)=>c===this.target[i]))this.cards.push(this.cards.shift());this.slots=Array(this.size).fill(null);this.index=Math.floor(Math.random()*(sequence.length-1));this.answer=sequence[this.index+1];this.options=shuffle([this.answer,...shuffle(sequence.filter(c=>c!==this.answer&&c!==sequence[this.index])).slice(0,3)]);this.choice=null}
 place(card,index){if(this.done||!this.target.includes(card)||index<0||index>=this.size)return;const old=this.slots.indexOf(card),displaced=this.slots[index];if(old>=0)this.slots[old]=displaced;this.slots[index]=card;this.feedback=''}
 remove(index){if(!this.done){this.slots[index]=null;this.feedback=''}}
 check(){if(this.done)return;const correct=this.mode==='order'?this.slots.every((c,i)=>c===this.target[i]):this.choice===this.answer;if(correct){this.done=true;this.solved++;this.feedback='Correct — this follows the usual filling sequence.'}else if(this.mode==='order'&&this.slots.includes(null)||this.mode==='next'&&!this.choice){this.feedback=this.mode==='order'?'Place all the subshell cards first.':'Select a subshell first.'}else{this.feedback=this.mode==='order'?'Not quite. Check the usual filling sequence and try again.':'Not quite. Try the next subshell in the usual filling sequence.'}}
 show(){this.revealed=true;this.done=true;if(this.mode==='order')this.slots=[...this.target];else this.choice=this.answer;this.feedback=this.mode==='order'?this.target.join(' → '):sequence[this.index]+' → '+this.answer}
}
if(typeof module!=='undefined'&&module.exports)module.exports={SubshellOrder,sequence};
if(typeof document==='undefined')return;
const root=document.getElementById('subshell-order-game');if(!root)return;
const game=new SubshellOrder(),el=id=>document.getElementById('sf-'+id);
function button(card,slot){return `<button type="button" class="sf-card" data-card="${card||''}"${slot===undefined?'':` data-slot="${slot}"`} aria-label="${slot===undefined?'Place '+card:'Position '+(slot+1)+(card?', '+card+', return card':', empty')}">${card||'<span>'+(slot+1)+'</span>'}</button>`}
function render(){el('progress').textContent=game.solved+' correct';el('order-panel').hidden=game.mode!=='order';el('next-panel').hidden=game.mode!=='next';el('size').textContent=game.size+' cards';el('bank').innerHTML=game.cards.filter(c=>!game.slots.includes(c)).map(c=>button(c)).join('');el('slots').innerHTML=game.slots.map((c,i)=>button(c,i)).join('');el('prompt').textContent=sequence[game.index]+' → ?';el('options').innerHTML=game.options.map(c=>`<button type="button" data-choice="${c}" aria-pressed="${game.choice===c}">${c}</button>`).join('');el('feedback').hidden=!game.feedback;el('feedback').textContent=game.feedback;el('feedback').className='of-feedback'+(game.done?(game.revealed?' answer':' success'):'');el('check').disabled=game.done;el('answer').disabled=game.done;root.querySelectorAll('[data-card],[data-choice]').forEach(b=>b.disabled=game.done)}
el('mode').addEventListener('change',e=>{game.mode=e.target.value;game.next();render()});
el('check').addEventListener('click',()=>{game.check();render()});el('answer').addEventListener('click',()=>{game.show();render()});el('next').addEventListener('click',()=>{game.next();render()});el('restart').addEventListener('click',()=>{game.solved=0;game.next();render()});
let drag=null,suppress=false;
root.addEventListener('click',e=>{if(suppress){suppress=false;return}const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.choice){game.choice=b.dataset.choice;game.feedback='';render();el('options').querySelector(`[data-choice="${game.choice}"]`).focus()}else if(b.hasAttribute('data-slot')){game.remove(Number(b.dataset.slot));render()}else if(b.dataset.card){const i=game.slots.indexOf(null);if(i>=0){game.place(b.dataset.card,i);render()}}});
root.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-card]');if(!b||!b.dataset.card||game.done||e.button!==0)return;drag={card:b.dataset.card,x:e.clientX,y:e.clientY,id:e.pointerId,ghost:null}});
window.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(!drag.ghost&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6){drag.ghost=document.createElement('div');drag.ghost.className='sf-ghost';drag.ghost.textContent=drag.card;document.body.append(drag.ghost)}if(drag.ghost){e.preventDefault();drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';root.querySelectorAll('.sf-drop').forEach(b=>b.classList.remove('sf-drop'));document.elementFromPoint(e.clientX,e.clientY)?.closest('#sf-slots [data-slot]')?.classList.add('sf-drop')}},{passive:false});
window.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;if(drag.ghost){const target=document.elementFromPoint(e.clientX,e.clientY),slot=target?.closest('#sf-slots [data-slot]');if(slot)game.place(drag.card,Number(slot.dataset.slot));else if(target?.closest('#sf-bank')){const i=game.slots.indexOf(drag.card);if(i>=0)game.remove(i)}drag.ghost.remove();suppress=true;setTimeout(()=>suppress=false,0);render()}drag=null});
window.addEventListener('pointercancel',()=>{drag?.ghost?.remove();drag=null;root.querySelectorAll('.sf-drop').forEach(b=>b.classList.remove('sf-drop'))});
render();
})();
